package io.agentplm.api;

import java.util.Map;

import io.agentplm.modules.season.SeasonValidationException;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.ext.ExceptionMapper;
import jakarta.ws.rs.ext.Provider;

@Provider
public class DomainExceptionMapper implements ExceptionMapper<RuntimeException> {

    @Override
    public Response toResponse(RuntimeException exception) {
        return switch (exception) {
            case SeasonValidationException e -> error(Response.Status.BAD_REQUEST, e.getMessage());
            case NotFoundException e -> error(Response.Status.NOT_FOUND, e.getMessage());
            case ConflictException e -> error(Response.Status.CONFLICT, e.getMessage());
